-- Phase 2: business type on tenants and the tenant_invitations table.
-- Generated by `pnpm db:generate` from src/modules/tenancy/infrastructure/schema.ts, then edited
-- by hand in one place: business_type is added with a temporary default so existing rows get a
-- value, and the default is dropped straight after (expand, then contract). Policies, grants and
-- the auth.users foreign keys follow in the next migration.
CREATE TABLE "rebook"."tenant_invitations" (
	"id" uuid PRIMARY KEY DEFAULT rebook.uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"email" text NOT NULL,
	"role" text NOT NULL,
	"token_hash" text NOT NULL,
	"invited_by" uuid,
	"expires_at" timestamp with time zone NOT NULL,
	"accepted_at" timestamp with time zone,
	"accepted_by" uuid,
	"revoked_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tenant_invitations_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "tenant_invitations_tenant_id_token_hash_unique" UNIQUE("tenant_id","token_hash"),
	CONSTRAINT "tenant_invitations_email_format" CHECK ("rebook"."tenant_invitations"."email" = lower(btrim("rebook"."tenant_invitations"."email")) and "rebook"."tenant_invitations"."email" ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' and length("rebook"."tenant_invitations"."email") <= 320),
	CONSTRAINT "tenant_invitations_role_valid" CHECK ("rebook"."tenant_invitations"."role" in ('owner', 'staff')),
	CONSTRAINT "tenant_invitations_token_hash_format" CHECK ("rebook"."tenant_invitations"."token_hash" ~ '^[0-9a-f]{64}$')
);
